    if (off + size > lfs->cfg->block_size) {
        return LFS_ERR_CORRUPT;
    }

    // Temporary buffer for reading from block device
    std::unique_ptr<uint8_t[]> read_buffer(new uint8_t[size]);

    // Read data from block device using cache-aware read
    lfs_size_t read_size = size;
    int err = lfs_bd_read(lfs, pcache, rcache, hint, block, off, read_buffer.get(), read_size);
    if (err) {
        return err;
    }

    // Compare the read data with the provided buffer
    const uint8_t *buffer_ptr = static_cast<const uint8_t*>(buffer);
    int cmp = std::memcmp(read_buffer.get(), buffer_ptr, size);

    if (cmp == 0) {
        return LFS_CMP_EQ;
    } else if (cmp < 0) {
        return LFS_CMP_LT;
    } else {
        return LFS_CMP_GT;
    }

